#include <vector>
#include <algorithm>

class Solution {
public:
    /**
     * 方法一：三次反轉（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    void rotate(vector<int>& nums, int k) {
        int n = nums.size();
        k = k % n;  // 處理 k > n 的情況

        // 三次反轉
        reverse(nums.begin(), nums.end());           // 反轉整個陣列
        reverse(nums.begin(), nums.begin() + k);     // 反轉前 k 個元素
        reverse(nums.begin() + k, nums.end());       // 反轉剩餘元素
    }

    /**
     * 方法二：使用額外陣列
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    void rotate_extra_space(vector<int>& nums, int k) {
        int n = nums.size();
        k = k % n;

        vector<int> result(n);

        // 將元素放到新位置
        for (int i = 0; i < n; i++) {
            result[(i + k) % n] = nums[i];
        }

        // 複製回原陣列
        nums = result;
    }
};

