class Solution {
    /**
     * 方法一：三次反轉（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k = k % n;  // 處理 k > n 的情況

        // 三次反轉
        reverse(nums, 0, n - 1);      // 反轉整個陣列
        reverse(nums, 0, k - 1);      // 反轉前 k 個元素
        reverse(nums, k, n - 1);      // 反轉剩餘元素
    }

    // 輔助函數：反轉陣列的 [left, right] 區間
    private void reverse(int[] nums, int left, int right) {
        while (left < right) {
            int temp = nums[left];
            nums[left] = nums[right];
            nums[right] = temp;
            left++;
            right--;
        }
    }

    /**
     * 方法二：使用額外陣列
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    public void rotate_extra_space(int[] nums, int k) {
        int n = nums.length;
        k = k % n;

        int[] result = new int[n];

        // 將元素放到新位置
        for (int i = 0; i < n; i++) {
            result[(i + k) % n] = nums[i];
        }

        // 複製回原陣列
        for (int i = 0; i < n; i++) {
            nums[i] = result[i];
        }
    }
}

